// Normalize enquiry: one shape for the web form and the test trigger.
const j = $input.first().json;
const pick = (...keys) => { for (const k of keys) { if (j[k] !== undefined && j[k] !== null && String(j[k]).trim() !== '') return String(j[k]).trim(); } return ''; };
const isTest = j.is_test === true || j.is_test === 'true';
const caseId = pick('case_id');
const stamp = $now.setZone('Europe/Warsaw').toFormat('yyyyMMdd-HHmmss');
const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
return [{ json: {
  enquiry_id: isTest ? 'TEST-' + caseId + '-' + $execution.id : 'MI-' + stamp + '-' + rand,
  received_at: $now.toISO(),
  channel: pick('channel') || 'web_form',
  requester_type: pick('requester_type', 'I am a') || 'other',
  product: pick('product', 'Product') || 'unknown',
  enquiry_text: pick('enquiry_text', 'Your question'),
  contact_name: pick('contact_name', 'Your name'),
  contact_email: pick('contact_email', 'Your email'),
  contact_phone: pick('contact_phone', 'Your phone (optional)'),
  is_test: isTest,
  case_id: caseId
} }];

// Mask personal data BEFORE any text goes to the AI.
// Replaces names, emails, phone numbers, ID numbers and dates of birth with typed placeholders.
const MASKING_VERSION = 'masking v1.0';
const e = $input.first().json;
const PRODUCT_WORDS = ['Velquanor', 'Orvatil', 'Brenquilo', 'Nordvale'];
const NOT_NAMES = new Set(['I', 'The', 'A', 'An', 'Is', 'Can', 'Could', 'What', 'How', 'Why', 'When', 'Please', 'Here', 'Hello', 'Hi', 'Dear', 'Thanks', 'Regards', ...PRODUCT_WORDS]);
const counts = { NAME: 0, EMAIL: 0, PHONE: 0, ID_NUMBER: 0, DATE_OF_BIRTH: 0 };
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
let text = String(e.enquiry_text || '');

// 1. Email addresses
text = text.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, () => { counts.EMAIL++; return '[EMAIL]'; });

// 2. Dates of birth (date that follows a cue such as DOB / born)
text = text.replace(/\b(DOB|D\.O\.B\.?|date of birth|born(?: on)?)(\s*:?\s*)\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}/gi,
  (m, cue, sep) => { counts.DATE_OF_BIRTH++; return cue + sep + '[DATE_OF_BIRTH]'; });

// 3. ID numbers that follow a cue (patient no., MRN, NHS no., PESEL, record no., insurance no.)
text = text.replace(/\b(patient (?:no\.?|number|id)|MRN|NHS(?: no\.?| number)?|PESEL|record (?:no\.?|number)|insurance (?:no\.?|number)|ID (?:no\.?|number))(\s*[:#]?\s*)([A-Z]{0,3}\d[\d -]{3,}\d)/gi,
  (m, cue, sep) => { counts.ID_NUMBER++; return cue + sep + '[ID_NUMBER]'; });

// 4. Phone numbers: a run of digits, spaces, dots, dashes or brackets with 9 or more digits
text = text.replace(/(?<![\w-])\+?\(?\d[\d\s().-]{7,}\d(?![\w-])/g, m => {
  const digits = (m.match(/\d/g) || []).length;
  if (digits >= 9) { counts.PHONE++; return '[PHONE]'; }
  return m;
});

// 5. Any other run of 6+ digits (record numbers without a cue)
text = text.replace(/(?<![\w-])\d{6,}(?![\w-])/g, () => { counts.ID_NUMBER++; return '[ID_NUMBER]'; });

// 6. The requester's own name, if it appears in the text (full name, then each part)
const contact = String(e.contact_name || '').trim();
if (contact) {
  const full = new RegExp('\\b' + esc(contact) + '\\b', 'gi');
  text = text.replace(full, () => { counts.NAME++; return '[NAME]'; });
  for (const part of contact.split(/\s+/).filter(p => p.length >= 3 && !NOT_NAMES.has(p))) {
    text = text.replace(new RegExp('\\b' + esc(part) + '\\b', 'g'), () => { counts.NAME++; return '[NAME]'; });
  }
}

// 7. Other people's names after a cue (Dr, Mr/Mrs/Ms, Patient, my name is, Thanks, Regards ...)
const CUE = /\b(Dr\.?|Doctor|Mr\.?|Mrs\.?|Ms\.?|Miss|Prof\.?|Professor|[Pp]atient|[Mm]y name is|I am|I'm|[Tt]his is|[Ss]igned|[Kk]ind regards,?|[Rr]egards,?|[Tt]hanks,?|[Tt]hank you,?|[Bb]est wishes,?|[Cc]heers,?)(\s+)((?:[A-Z][a-zA-ZÀ-ÿ'’-]+)(?:\s+[A-Z][a-zA-ZÀ-ÿ'’-]+){0,2})/g;
text = text.replace(CUE, (m, cue, sp, name) => {
  const words = name.split(/\s+/);
  if (NOT_NAMES.has(words[0])) return m;
  counts.NAME++;
  return cue + sp + '[NAME]';
});
text = text.replace(/\[NAME\](\s+\[NAME\])+/g, '[NAME]');

const total = Object.values(counts).reduce((a, b) => a + b, 0);
return [{ json: { ...e, masked_text: text, masked_count: total, masked_types: counts, masking_version: MASKING_VERSION } }];

// Check masking: scan the masked text again. If anything that looks like personal data is left,
// the AI is NOT called and the enquiry goes to a human.
const e = $input.first().json;
const text = String(e.masked_text || '');
const findings = [];
if (/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(text)) findings.push('email');
const phoneLike = text.match(/(?<![\w-])\+?\(?\d[\d\s().-]{7,}\d(?![\w-])/g) || [];
if (phoneLike.some(m => (m.match(/\d/g) || []).length >= 9)) findings.push('phone');
if (/(?<![\w-])\d{6,}(?![\w-])/.test(text)) findings.push('long_number');
if (/\b(DOB|date of birth|born)\s*:?\s*\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}/i.test(text)) findings.push('date_of_birth');
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
for (const v of [e.contact_name, e.contact_email].map(x => String(x || '').trim()).filter(Boolean)) {
  if (new RegExp('\\b' + esc(v) + '\\b', 'i').test(text)) findings.push('contact_details');
}
const phoneDigits = String(e.contact_phone || '').replace(/\D/g, '');
if (phoneDigits.length >= 6 && text.replace(/\D/g, '').includes(phoneDigits)) findings.push('contact_phone');
if (/\b(Dr\.?|Mr\.?|Mrs\.?|Ms\.?|[Pp]atient|[Mm]y name is)\s+[A-Z][a-z]+\s+[A-Z][a-z]+/.test(text)) findings.push('possible_name');
return [{ json: { ...e, pii_ok: findings.length === 0, pii_findings: [...new Set(findings)].join(', ') } }];

// AE keyword rules: an independent, AI-free check for possible adverse events and special situations.
// A hit here sends the enquiry to Drug Safety even if the AI disagrees or is down.
const RULES_VERSION = 'ae-rules v1.0';
const e = $input.first().json;
const text = String(e.masked_text || '');
const RULES = [
  ['side effect / reaction', /\bside[\s-]?effects?\b|\badverse\b|\breactions?\b/i],
  ['skin symptom', /\brash(es)?\b|\bhives\b|\bitch(y|ing)?\b|\burticaria\b|\bswell(ing|ed)?\b|\bswollen\b|\bburn(ing|s|ed)?\b|\bredness\b|\band red\b|\bred and\b|\bpeeling\b/i],
  ['pain', /\b(pain|aches?|aching|headaches?|migraine|cramps?)\b/i],
  ['dizziness / fainting', /\b(dizz(y|iness)|faint(ed|ing)?|light-?headed|passed out|collapsed?)\b/i],
  ['stomach symptom', /\b(nause(a|ous)|vomit(ed|ing|s)?|threw up|throwing up|diarrh(o)?ea|stomach upset)\b/i],
  ['heart / breathing', /\b(palpitations?|chest pain|short(ness)? of breath|breathless|wheez(e|ing)|racing heart)\b/i],
  ['nervous system', /\b(seizures?|convulsions?|sleepy|drowsy|drowsiness|confus(ed|ion)|tremor|shaking)\b/i],
  ['serious outcome', /\b(hospital(ised|ized)?|A&E|emergency|ambulance|intensive care|died|death|fatal|life[- ]threatening)\b/i],
  ['felt unwell', /\b(felt|feel|feeling|been|got|became|getting) (unwell|ill|sick|worse|awful|terrible)\b/i],
  ['overdose / medication error', /\b(overdose|too (much|many)|by mistake|accidental(ly)?|wrong (dose|medicine|tablet|product)|took (two|2|double|extra))\b/i],
  ['child exposure', /\b(my|our|a|her|his) (son|daughter|child|baby|toddler|kid|grandchild)\b.{0,60}\b(took|swallowed|ate|drank|got into)\b/i],
  ['pregnancy / breastfeeding', /\bpregnan(t|cy)\b|\bbreast-?feeding\b/i],
  ['lack of effect', /\b(doesn'?t|does not|didn'?t|did not|stopped|no longer) (work|working|help|helping|do anything|doing anything)\b|\bnot (working|helping)\b|\bno effect\b|\bas bad as before\b|\bineffective\b/i],
  ['after use', /\bafter (taking|using|applying|starting|the (tablets?|cream|dose|medicine|solution))\b.{0,80}\b(got|developed|had|started|noticed|became)\b/i],
  ['since starting', /\bsince (starting|she started|he started|I started|they started|taking|using)\b/i],
];
const hits = RULES.filter(([, re]) => re.test(text)).map(([label]) => label);
return [{ json: { ...e, ae_rule: hits.length > 0, ae_terms: hits.join(', '), rules_version: RULES_VERSION } }];

// Build AI request: the model gets only masked text, requester type, product,
// and the list of approved response IDs (titles and scope, never the response text).
const PROMPT_VERSION = 'prompt v1.0';
const e = $('AE keyword rules').first().json;
const library = $input.all().map(i => i.json).filter(r => r.response_id && r.status === 'approved');
const options = library
  .filter(r => r.product === e.product || r.product === 'ALL')
  .map(r => '- ' + r.response_id + ' | ' + r.title + ' | scope: ' + r.scope)
  .join('\n');
const userMessage =
  '<enquiry>\n' +
  'requester_type: ' + e.requester_type + '\n' +
  'product: ' + e.product + '\n' +
  'text: ' + e.masked_text + '\n' +
  '</enquiry>\n\n' +
  '<approved_responses>\n' + (options || '(none for this product)') + '\n</approved_responses>';
return [{ json: { ...e, ai_prompt: userMessage, prompt_version: PROMPT_VERSION } }];

// Route enquiry: combines the rule check and the AI result, applies the routing rules,
// builds a draft ONLY from approved library text, and runs the code checks.
const WORKFLOW_VERSION = 'pic-mi-triage v1.1';
const CATEGORIES = ['product_information', 'adverse_event', 'product_complaint', 'off_label', 'other'];
const FORBIDDEN = [
  /\byou should (take|stop|start|increase|decrease|use|apply)\b/i, /\bstop taking\b/i,
  /\b(increase|decrease|double|halve) (your|the) dose\b/i, /\bsafe for you\b/i, /\bcompletely safe\b/i,
  /\b100% safe\b/i, /\bno side effects\b/i, /\bguarantee/i, /\bcures?\b/i, /\bI recommend\b/i,
  /\bwe recommend\b/i, /\bin my opinion\b/i, /\bdiagnos/i, /\bno need to see (a|your) doctor\b/i
];

const e = $('AE keyword rules').first().json;
let library = [];
try { library = $('Get response library').all().map(i => i.json).filter(r => r.response_id); } catch (err) { library = []; }
let aiPrompt = '';
try { aiPrompt = $('Build AI request').first().json.ai_prompt || ''; } catch (err) { aiPrompt = ''; }

// --- AI result (may be missing) ---
function aiText(j) {
  if (typeof j.merged_response === 'string') return j.merged_response;
  if (Array.isArray(j.content)) return j.content.filter(p => p && p.type === 'text').map(p => p.text).join('');
  if (typeof j.text === 'string') return j.text;
  if (typeof j.output === 'string') return j.output;
  return '';
}
// Pull every top-level {...} block out of the reply (the model sometimes repeats its JSON).
function jsonBlocks(text) {
  const out = []; let depth = 0, start = -1, inStr = false, esc = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') inStr = true;
    else if (ch === '{') { if (depth === 0) start = i; depth++; }
    else if (ch === '}' && depth > 0) { depth--; if (depth === 0) out.push(text.slice(start, i + 1)); }
  }
  return out;
}
// Accept the reply only if every valid block agrees on the category.
// If any block flags an adverse event, the flag wins; if blocks cite different responses, no response is used.
function parse(text) {
  const valid = [];
  for (const b of jsonBlocks(text)) {
    try { const o = JSON.parse(b); if (CATEGORIES.includes(o.category) && typeof o.ae_suspected === 'boolean') valid.push(o); } catch (err) {}
  }
  if (!valid.length) return null;
  const anyAe = valid.some(o => o.ae_suspected === true || o.category === 'adverse_event');
  if (new Set(valid.map(o => o.category)).size > 1) {
    // Blocks disagree: keep any safety signal, otherwise treat the reply as invalid.
    return anyAe ? { category: 'adverse_event', ae_suspected: true, ae_reason: 'conflicting AI blocks, one flags a possible AE', response_id: 'NONE', rationale: 'conflicting AI output', json_blocks: valid.length } : null;
  }
  const ids = new Set(valid.map(o => String(o.response_id || 'NONE')));
  const last = valid[valid.length - 1];
  return { ...last, ae_suspected: anyAe,
    ae_reason: valid.map(o => o.ae_reason).filter(Boolean).join('; '),
    response_id: ids.size === 1 ? last.response_id : 'NONE', json_blocks: valid.length };
}
const aiCalled = e.pii_ok === true;
let ai = null, aiStatus = 'not_called';
if (aiCalled) {
  const raw = $input.first().json;
  const parsed = raw.error ? null : parse(aiText(raw));
  if (!raw.error && parsed) { ai = parsed; aiStatus = parsed.json_blocks > 1 ? 'ok (' + parsed.json_blocks + ' JSON blocks merged)' : 'ok'; }
  else aiStatus = raw.error ? 'ai_unavailable' : 'ai_invalid_output';
}
const aeAi = !!ai && (ai.ae_suspected === true || ai.category === 'adverse_event');
const category = ai ? ai.category : '';

// --- Checks shared by all paths ---
const checks = [];
// PII check on the exact text that was sent to the AI
const piiPatterns = [/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i, /(?<![\w-])\d{6,}(?![\w-])/];
const contactBits = [e.contact_name, e.contact_email].map(x => String(x || '').trim()).filter(Boolean);
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const phoneDigits = String(e.contact_phone || '').replace(/\D/g, '');
const promptLeak = aiPrompt && (piiPatterns.some(re => re.test(aiPrompt))
  || contactBits.some(v => new RegExp('\\b' + esc(v) + '\\b', 'i').test(aiPrompt))
  || (phoneDigits.length >= 6 && aiPrompt.replace(/\D/g, '').includes(phoneDigits)));
checks.push(aiCalled ? (promptLeak ? 'pii_in_ai_text:FAIL' : 'pii_in_ai_text:pass') : 'pii_in_ai_text:not_sent');

// --- Routing (order matters: safety first) ---
let queue, reason = '', draft = '', sourceId = '', sourceVersion = '';
if (!e.pii_ok) { queue = 'mi_human'; reason = 'pii_check_failed: ' + e.pii_findings; }
else if (e.ae_rule || aeAi) {
  queue = 'drug_safety';
  reason = 'possible adverse event: ' + [e.ae_rule ? 'rules (' + e.ae_terms + ')' : '', aeAi ? 'AI (' + (ai.ae_reason || ai.category) + ')' : ''].filter(Boolean).join(' + ');
}
else if (!ai) { queue = 'mi_human'; reason = aiStatus; }
else if (category === 'product_complaint') { queue = 'quality'; reason = 'product complaint'; }
else if (category === 'off_label') { queue = 'senior_mi'; reason = 'off-label question: senior MI reviewer only'; }
else if (category === 'product_information') {
  const wanted = String(ai.response_id || 'NONE').trim();
  if (wanted === 'NONE' || !wanted) { queue = 'mi_human'; reason = 'no approved response matches'; }
  else {
    const current = library.filter(r => r.response_id === wanted && r.status === 'approved' && (r.product === e.product || r.product === 'ALL'));
    if (current.length !== 1) {
      queue = 'mi_human'; reason = 'citation_check_failed: ' + wanted + ' is not an approved response for ' + e.product;
      checks.push('citation:FAIL');
    } else {
      const src = current[0];
      draft = 'Thank you for your enquiry about ' + e.product + '.\n\n' + src.text + '\n\n' +
        'This is general product information, not medical advice. For advice about an individual patient or your own treatment, please speak to a doctor or pharmacist.\n\n' +
        '[Source: ' + src.response_id + ' v' + src.version + ']';
      sourceId = src.response_id; sourceVersion = src.version;
      // Citation check: the cited ID and version exist in the library and are approved
      const citedOk = library.some(r => r.response_id === sourceId && r.version === sourceVersion && r.status === 'approved');
      checks.push(citedOk ? 'citation:pass' : 'citation:FAIL');
      // Forbidden phrases check on the whole draft
      const bad = FORBIDDEN.filter(re => re.test(draft)).map(re => re.source);
      checks.push(bad.length ? 'forbidden_phrases:FAIL' : 'forbidden_phrases:pass');
      if (!citedOk || bad.length || promptLeak) {
        queue = 'mi_human';
        reason = 'draft blocked by checks: ' + checks.filter(c => c.endsWith('FAIL')).join(', ');
        draft = ''; sourceId = ''; sourceVersion = '';
      } else { queue = 'draft_review'; reason = 'draft from approved response'; }
    }
  }
}
else { queue = 'mi_human'; reason = 'category other'; }

return [{ json: {
  enquiry_id: e.enquiry_id, case_id: e.case_id, is_test: e.is_test, created_at: $now.toISO(),
  requester_type: e.requester_type, product: e.product,
  queue, status: queue === 'draft_review' ? 'pending_review' : 'open',
  category: category || 'unclassified', ai_status: aiStatus,
  ae_rule: !!e.ae_rule, ae_ai: aeAi, ae_terms: e.ae_terms || '',
  rationale: ai ? String(ai.rationale || '') : '', ai_response_id: ai ? String(ai.response_id || '') : '',
  reason, masked_text: e.masked_text, masked_count: e.masked_count, ai_prompt: aiPrompt,
  draft_text: draft, source_id: sourceId, source_version: sourceVersion, checks: checks.join(', '),
  workflow_version: [WORKFLOW_VERSION, e.masking_version, e.rules_version, aiCalled ? 'prompt v1.0' : ''].filter(Boolean).join(' / ')
} }];
